			written = { ["Back to {npc:11802}"] = "Back to Dendrite", ["Back to {npc:11802} in {area:2361}, then {npc:11800} there flies Druids straight to {area:702}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Back to Dendrite Starblaze in Nighthaven, then Silva Fil'naveth there flies Druids straight to Rut'theran Village. Dendrite stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", ["Cast {spell:18960}. With both half pendants in your bags, stand by the {area:2362} on the north-west shore of the lake and use a half to join them, then go to {npc:11802} in {area:2361}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Cast Teleport: Moonglade. With both half pendants in your bags, stand by the Shrine of Remulos on the north-west shore of the lake and use a half to join them, then go to Dendrite Starblaze in Nighthaven. Dendrite stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", ["Into {zone:1453}"] = "Into Stormwind City", ["Take the portal up to {npc:4217}, then fly back to {area:442} for the road south to {zone:1440}. {npc:4217} is a Druid trainer: learn your new spells from him."] = "Take the portal up to Mathrengyl, then fly back to Auberdine for the road south to Ashenvale. Mathrengyl is a Druid trainer: learn your new spells from him.", ["{npc:11802}: the welcome from {npc:5504}"] = "Dendrite Starblaze: the welcome from Sheldras", ["{quest:87760}: {npc:10219} offers it once all nine beached remains are handed in"] = "Holy Diver: Gwennyth offers it once all nine beached remains are handed in" },
