396"] = "Sentinel Dalia Sunblade", ["npc:8583"] = "Dirania Silvershine", ["npc:8584"] = "Iverron", ["object:126158"] = "Tallonkai's Dresser", ["object:1673"] = "Fel Cone", ["object:175207"] = "Beached Sea Creature", ["object:4406"] = "Webwood Eggs", ["object:673378"] = "Oracle Tree Bark", ["object:6752"] = "Strange Fronded Plant", ["object:7510"] = "Sprouted Frond", ["quest:1683"] = "Vorlus Vilehoof", ["quest:1684"] = "Elanaria", ["quest:2459"] = "Ferocitas the Dream Eater", ["quest:2520"] = "Sathrah's Sacrifice", ["quest:3116"] = "Simple Sigil", ["quest:3118"] = "Encrypted Sigil", ["quest:3119"] = "Hallowed Sigil", ["quest:3120"] = "Verdant Sigil", ["quest:3521"] = "Iverron's Antidote", ["quest:489"] = "Seek Redemption!", ["quest:6063"] = "Taming the Beast", ["quest:6342"] = "Flight to Auberdine", ["quest:6343"] = "Return to Nessa", ["quest:917"] = "Webwood Egg", ["quest:919"] = "Timberling Sprouts", ["quest:922"] = "Rellian Greenspyre", ["quest:932"] = "Twisted Hatred", ["quest:938"] = "Mist", ["quest:940"] = "Teldrassil", ["quest:97236"] = "Fang of Githyiss", ["quest:97979"] = "The Goddess Provides", ["quest:983"] = "Buzzbox 827", ["quest:99053"] = "Escaping Ban'ethil", ["spell:1243"] = "Power Word: Fortitude", ["spell:1259799"] = "Elune's Light", ["spell:1515"] = "Tame Beast", ["spell:19684"] = "Tame Webwood Lurker", ["spell:19685"] = "Tame Nightsaber Stalker", ["spell:19686"] = "Tame Strigid Screecher", ["spell:5149"] = "Beast Training", ["spell:613"] = "Lesser Heal", ["spell:71"] = "Defensive Stance", ["zone:1457"] = "Darnassus" },
			written = { ["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "Fel Cones lie under the trees all around Dolanaar and Zenn: pick them up on the road east and hand them to Zenn on the way to Ferocitas.", ["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442}."] = "Fly back to Rut'theran Village from Caylais Moonfeather, hand Laird's Response to Nessa on the dock, then fly back to Auberdine.", ["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "Follow the road south-west out of Shadowglen. Zenn sits beside it just east of Dolanaar.", ["Gnarlpine Mystics and {npc:7234} camp north-east of {area:260}. {npc:7234} drops the {item:8049}: open it for the jewel.\nCareful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard."] = "Gnarlpine Mystics and Ferocitas camp north-east of Starbreeze Village. Ferocitas drops the Gnarlpine Necklace: open it for the jewel.\nCareful: Ferocitas waits near the camp fire with mystics around him, so pulling him without adds is hard.", ["Level 12 spells while you're in the Temple of the {npc:2151}: the priest trainers stand beside {npc:11401}."] = "Level 12 spells while you're in the Temple of the Moon: the priest trainers stand beside Priestess Alathea.", ["South-west of Starbreeze, south of {npc:2150}. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "South-west of Starbreeze, south of Zenn. Denalan tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the Timberling Sprouts grow among them.", ["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs. Once you have {quest:6342}, talk to {npc:3838} again and choose the flight to {area:442}: it is free and lands beside {npc:4200}. If the flight map opens instead, close it and talk to him again holding Shift."] = "Take the portal down to Rut'theran Village. Nessa stands on the dock, Vesprystus by the hippogryphs. Once you have Flight to Auberdine, talk to Vesprystus again and choose the flight to Auberdine: it is free and lands beside Laird. If the flight map opens instead, close it and talk to him again holding Shift.", ["The road west to the {area:264} runs through {area:186}: hand {npc:3567} the jewel on the way."] = "The road west to the Oracle Glade runs through Dolanaar: hand Tallonkai the jewel on the way.", ["{area:264}"] = "The Oracle Glade", ["{item:8049}, from {npc:7234}"] = "Gnarlpine Necklace, from Ferocitas", ["{npc:11401}, in the Temple of the {npc:2151}: Starshards"] = "Priestess Alathea, in the Temple of the Moon: Starshards", ["{npc:2150} sits by the road just east of {area:186}, between {area:186} and {area:260}."] = "Zenn sits by the road just east of Dolanaar, between Dolanaar and Starbreeze Village.", ["{npc:3516} is in the {area:1658} at the north end of the city, {quest:922} just south of it. {npc:4092}, {npc:7999}, {npc:7313} and {npc:8396} are in the Temple of the {npc:2151} at the south end. Into the city through the gate. {quest:922} is just south of the {area:1658} at the north end, {npc:7316} in the west, {npc:7313} and {npc:8396} in the Temple of the {npc:2151} at the south end. On the way back out, use Dalia's {item:279378} at the bank and at the city gate; the other two owls wait for your last visit."] = "Arch Druid Fandral Staghelm is in the Cenarion Enclave at the north end of the city, Rellian Greenspyre just south of it. Lariia, Tyrande Whisperwind, Priestess A'moora and Sentinel Dalia Sunblade are in the Temple of the Moon at the south end. Into the city through the gate. Rellian Greenspyre is just south of the Cenarion Enclave at the north end, Sister Aquinne in the west, Priestess A'moora and Sentinel Dalia Sunblade in the Temple of the Moon at the south end. On the way back out, use Dalia's Lunar Pendant at the bank and at the city gate; the other two owls wait for your last visit.", ["{npc:4092}, in the Temple of the {npc:2151}"] = "Lariia, in the Temple of the Moon", ["{npc:7313}, in the Temple of the {npc:2151}"] = "Priestess A'moora, in the Temple of the Moon", ["{npc:7318} (level 10), {npc:7317}'s soulless body, walks around {area:736} in the den: kill him, then use {npc:7317}'s {item:8149}."] = "Rageclaw (level 10), Oben's soulless body, walks around Ban'ethil Hollow in the den: kill him, then use Oben's Voodoo Charm." },
