					when = { { k = "turnedin", neg = true, q = 6064 }, { k = "turnedin", neg = true, q = 6063 } },
					goals = {
						{ t = "kill", quest = 94863, title = "Taming the Beast", target = "Gray Forest Wolf", npc = 1922, count = 1, oi = 1, text = "Tame {npc:1922}", map = 1429, x = 58.4, y = 62.1, z = 69.4, f = "e", spotsPacked = "59.8,64.4,73.7,73,10;61,60.8,,40,3;64.6,60.3,67.9,40,1;65,64.3,65.8,64,4;66.2,67.8,60.3,40,1;67.8,63,,42,4;70.6,62.1,64.6,49,6;73.5,63.9,61.2,40,3;73.1,67.3,55.3,56,4;69.9,69.5,46.1,40,1;68,58.3,70,56,4;61.2,70.8,,40,3;60.2,67.5,,57,6,1;63.1,69,62.4,40,1,1;68.7,65,60.6,40,3,1", spread = true, lvl = 8, note = "Use the {item:266253} on a living wolf" },
						{ t = "turnin", quest = 94863, title = "Taming the Beast", npc = 251507, npcName = "Josephine Carson", map = 1429, x = 41.2, y = 66.3 },
						{ t = "accept", quest = 94864, title = "Taming the Beast", npc = 251507, npcName = "Josephine Carson", minLevel = 10, qlvl = 10, pre = { 94863 }, preTitles = { [94863] = "Taming the Beast" }, map = 1429, x = 41.2, y = 66.3 },
					},
				},
				{
					title = "{npc:822}",
					note = "Dismiss the wolf. Young Forest Bears (level 8-9) roam the woods just south of {area:87}, with more south-west and south-east of town.",
					when = { { k = "turnedin", neg = true, q = 6064 }, { k = "turnedin", neg = true, q = 6063 } },
					goals = {
						{ t = "kill", quest = 94864, title = "Taming the Beast", target = "Young Forest Bear", npc = 822, count = 1, oi = 1, text = "Tame {npc:822}", map = 1429, x = 46.3, y = 75.8, z = 39.4, f = "e", spotsPacked = "46.8,79.4,,136,8;53.5,84.7,,79,1;62.7,78.7,,119,5;62.2,65.3,,114,3;69.6,63.8,,83,3;76.8,64.4,,96,4;87,65.6,,86,5;83.5,84.7,33.3,79,1;72.9,80.9,39.4,79,1;37.3,89.3,,79,2;25.5,90.7,38.3,79,1;22.4,75.8,,79,1;55.4,75.7,,79,2,1;26.7,82.5,,80,2,1;70.6,74.9,42.3,79,1,1;79.1,79.1,,101,4,1;82.2,59.2,,79,1,1;87.7,79,,79,3,1", spread = true, lvl = 9, note = "Use the {item:266254} on a living bear" },
						{ t = "turnin", quest = 94864, title = "Taming the Beast", npc = 251507, npcName = "Josephine Carson", map = 1429, x = 41.2, y = 66.3, note = "{npc:251507}: {spell:1515}" },
						{ t = "accept", quest = 94793, title = "Training the Beast", npc = 251507, npcName = "Josephine Carson", minLevel = 10, qlvl = 10, pre = { 94864 }, preTitles = { [94864] = "Taming the Beast" }, map = 1429, x = 41.2, y = 66.3 },
						{ t = "turnin", quest = 94793, title = "Training the Beast", npc = 258930, npcName = "Isaac Chan", map = 1429, x = 41.7, y = 66.4, note = "{npc:258930}, beside her: {spell:5149}" },
					},
				},
				{
					title = "Your first pet",
					note = "{spell:1515} works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and {spell:17253}) and a boar takes more punishment.",
					label = "pet",
					goals = {
						{ t = "task", text = "Tame a beast of your level to keep", optional = true },
						{ t = "note", text = "Near {area:87} there are no cats: Prowlers (wolves, level 9-10) roam eastern Elwynn, Longsnouts (boars, 10-11) its far south-west by the {zone:1436} border; at 12-13, Young Goretusks (boars) graze the fields of northern {zone:1436}.", only = { races = { "Human" } } },
						{ t = "note", text = "Near {area:131}: Snow Leopards (cats, level 7-8) prowl all over {zone:1426}, Scarred Crag Boars (9-10) its east toward {zone:1432}; at 10-11, Mountain Boars roam western {zone:1432}.", only = { races = { "Dwarf" } } },
						{ t = "note", text = "Near {area:186}: Elder Nightsabers (cats, level 8-9) and Feral Nightsabers (cats, 10-11) prowl the woods of north-western {zone:1438}.", only = { races = { "NightElf" } } },
						{ t = "note", text = "Near {area:16638}: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the {area:16626}; Shriekling Matriarchs (raptors, level 9) nest just west of {area:16638}; Shadowgale Urseras (bears, 10-11) roam the north of {zone:2665}.", only = { races = { "Skyborne" } } },
						{ t = "note", text = "{spell:1584}: open your spellbook, cast {spell:1584} and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Toddrick the butcher in {area:87}, Jaeana in {zone:1457} and the innkeepers on {zone:2665} sell meat; the innkeepers of {area:131} and {area:186} sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat." },
						{ t = "note", text = "Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away." },
						{ t = "note", text = "Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in {spell:5149} (pet level times loyalty rank minus one)." },
						{ t = "note", text = "{spell:5149} (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master (Erma in {area:87}, {npc:9980} in {area:131}, Seriadne in {area:186}, {npc:265756} on {zone:2665}), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with {spell:5149}. A pet holds four active abilities at most." },
						{ t = "note", text = "Pet trainers sell {spell:1853} ranks and resistances. Alliance: {npc:258930} in {area:87}, {npc:2879} by the hunter trainers in {zone:1453}'s {object:28027}, {npc:2878} in {area:131}, {npc:10090} in {zone:1455}'s {object:32390}, Keldas in {area:186}, Silvaria in {zone:1457}' Cenarion Enclave, {npc:254411} in {area:16638}." },
						{ t = "note", text = "{spell:883}, {spell:2641} and {spell:982} are in your spellbook now; {spell:136} comes from your trainer at 12. A dead pet needs {spell:982}; one that is away more than about 100 yards is dismissed and comes back with {spell:883}." },
					},
				},
			},
		})
	end
	register()
end

