						{ t = "collect", quest = 1920, title = "Investigate the Blue Recluse", item = 7292, itemName = "Filled Containment Coffer", count = 3, oi = 1, map = 1453, x = 51.3, y = 93.3, spotsPacked = "51.15,93.48,,27", from = "Filled Containment Coffer", fromKind = "object", fromId = 103574 },
