						{ t = "collect", quest = 1654, title = "The Test of Righteousness", item = 7083, itemName = "Purified Kor Gem", count = 1, oi = 4 },
					},
				},
				{
					title = "{item:6953}",
					note = "Bring the four parts to {npc:6181} outside {zone:1455}. Accept his last quest and wait by him while he forges the mace at his anvil.",
					goals = {
						{ t = "turnin", quest = 1654, title = "The Test of Righteousness", npc = 6181, npcName = "Jordan Stilwell", map = 1426, x = 52.5, y = 36.9, z = 495.3, f = "e" },
