					note = "Bring the {item:6656} back to Teo inside {area:77}. Keep the {item:5175} in your bags for good: every earth totem needs it.",
					goals = {
						{ t = "turnin", quest = 94375, title = "Call of Earth", npc = 257446, npcName = "Teo Hammerstorm", map = 1426, x = 28.8, y = 66.2, z = 399, note = "{npc:257446}: {spell:8071} and your {item:5175}", rewards = { items = { { item = 5175, itemName = "Earth Totem" } } } },
						{ t = "train", class = true, zone = 1426, note = "the level 4 shaman spells", candidates = { { npc = 257446, npcName = "Teo Hammerstorm", map = 1426, x = 28.8, y = 66.2, z = 399, faction = "AH", classes = { "SHAMAN" } }, { npc = 258113, npcName = "Ingrid Dunwald", map = 1426, x = 47.6, y = 52, z = 403.6, faction = "AH", classes = { "SHAMAN" } }, { npc = 258098, npcName = "Eldrun Stormbreaker", map = 1455, x = 47.3, y = 13.5, faction = "A", classes = { "SHAMAN" } } } },
