			zone = 1455,
			zoneName = "Ironforge",
			author = "Polestar",
			version = 1,
			names = { ["area:108"] = "Sentinel Hill", ["area:144"] = "Thelsamar", ["area:146"] = "Stonewrought Dam", ["area:150"] = "Menethil Harbor", ["area:20"] = "Moonbrook", ["area:271"] = "Southshore", ["area:415"] = "Astranaar", ["area:442"] = "Auberdine", ["area:68"] = "Lake Everstill", ["area:69"] = "Lakeshire", ["area:71"] = "Stonewatch Falls", ["area:836"] = "Dun Algaz", ["area:919"] = "Stendel's Pond", ["item:5177"] = "Water Totem", ["item:6637"] = "Water Sapta", ["item:7810"] = "Vial of Purest Water", ["item:7811"] = "Remaining Drops of Purest Water", ["item:7813"] = "Shard of Water", ["npc:258043"] = "Norric Lochthane", ["npc:258098"] = "Eldrun Stormbreaker", ["npc:258203"] = "Hervdana Saegrund", ["npc:544"] = "Murloc Nightcrawler", ["npc:5894"] = "Corrupt Minor Manifestation of Water", ["npc:5895"] = "Minor Manifestation of Water", ["object:147516"] = "Dark Iron", ["object:32362"] = "Mystic Ward", ["object:619896"] = "Forgotten Shrine", ["quest:94494"] = "Call of Water", ["quest:94616"] = "Water Sapta", ["spell:122"] = "Frost Nova", ["spell:5394"] = "Healing Stream Totem", ["spell:8056"] = "Frost Shock", ["zone:1432"] = "Loch Modan", ["zone:1436"] = "Westfall", ["zone:1437"] = "Wetlands", ["zone:1439"] = "Darkshore", ["zone:1440"] = "Ashenvale", ["zone:1455"] = "Ironforge" },
			written = { ["Back to {npc:258043} by {area:146} with the {item:7810}. He hands you the {item:6637} and the {item:7811}: keep both for {zone:1436}."] = "Back to Norric by Stonewrought Dam with the Vial of Purest Water. He hands you the Water Sapta and the Remaining Drops of Purest Water: keep both for Westfall.", ["Back to {npc:258043} with the {item:7813}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "Back to Norric with the Shard of Water. Keep the Water Totem in your bags for good: every water totem needs it.", ["Fill the Unfilled Brown Waterskin at the bottom of the waterfalls below {npc:258203}'s cave, where the fresh water meets the brackish. {object:147516} dwarves roam near the falls."] = "Fill the Unfilled Brown Waterskin at the bottom of the waterfalls below Hervdana's cave, where the fresh water meets the brackish. Dark Iron dwarves roam near the falls.", ["Fly to {area:108} and head south to {area:20}: {area:919} and the {object:619896} lie just north of it. Drink the {item:6637} by the shrine to see the {npc:5894} (level 22, {spell:8056} and {spell:122}; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the {item:7811} on the {object:619896} (this, not {npc:258043}, ends the quest). Click the shrine again: the {npc:5895} rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the {item:7813}."] = "Fly to Sentinel Hill and head south to Moonbrook: Stendel's Pond and the Forgotten Shrine lie just north of it. Drink the Water Sapta by the shrine to see the Corrupt Minor Manifestation of Water (level 22, Frost Shock and Frost Nova; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the Remaining Drops of Purest Water on the Forgotten Shrine (this, not Norric, ends the quest). Click the shrine again: the Minor Manifestation of Water rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the Shard of Water.", ["Only if the {quest:94616} is gone from your bags: {npc:258043} gives you another before you leave for {zone:1436}."] = "Only if the Water Sapta is gone from your bags: Norric gives you another before you leave for Westfall.", ["the {item:7810}, for {npc:258043}"] = "the Vial of Purest Water, for Norric", ["{area:71} pour out of {area:68} at the east end of Redridge (fly from {zone:1455} to {area:69}). Fill the Unfilled Red Waterskin at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from {npc:258203} for a new one."] = "Stonewatch Falls pour out of Lake Everstill at the east end of Redridge (fly from Ironforge to Lakeshire). Fill the Unfilled Red Waterskin at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from Hervdana for a new one.", ["{npc:258043}'s burrow hut stands on the north-western shore of the loch, below {area:146}, north of {area:144}."] = "Norric's burrow hut stands on the north-western shore of the loch, below Stonewrought Dam, north of Thelsamar.", ["{npc:258203}'s family lives in a cave beneath the southern falls of the {zone:1437}, east of {area:836}: not in a town. Through the Algaz tunnel north of {zone:1432}, then east off the road."] = "Hervdana's family lives in a cave beneath the southern falls of the Wetlands, east of Dun Algaz: not in a town. Through the Algaz tunnel north of Loch Modan, then east off the road." },
			steps = {
				{
					title = "{npc:258098}",
					note = "At 20 {npc:258098}, the shaman trainer in {zone:1455}'s {object:32362}, sends you to {npc:258043} in {zone:1432}.",
					goals = {
						{ t = "level", level = 20 },
						{ t = "accept", quest = 94494, title = "Call of Water", npc = 258098, npcName = "Eldrun Stormbreaker", minLevel = 20, qlvl = 20, map = 1455, x = 47.28, y = 13.52, spotsPacked = "47.3,13.5,,15,10" },
