						{ t = "accept", quest = 1804, title = "Tome of the Cabal", npc = 6294, npcName = "Krom Stoutarm", minLevel = 30, qlvl = 30, pre = { 1802 }, preTitles = { [1802] = "Tome of the Cabal" }, map = 1455, x = 74.2, y = 9.4, z = 503.5, f = "e" },
