						{ t = "accept", quest = 1795, title = "The Binding", npc = 6251, npcName = "Strahad Farsan", minLevel = 30, qlvl = 30, pre = { 1804, 1805 }, preTitles = { [1804] = "Tome of the Cabal", [1805] = "Tome of the Cabal" }, map = 1413, x = 62.6, y = 35.5, z = 40.5, f = "e" },
						{ t = "use", item = 6999, itemName = "Tome of the Cabal", map = 1413, x = 62.6, y = 35.3, f = "e", note = "{quest:1804}, on the circle" },
						{ t = "kill", quest = 1795, title = "The Binding", target = "Summoned Felhunter", npc = 6268, count = 1, oi = 1, map = 1417, x = 79.3, y = 26.5, f = "e" },
