						{ t = "accept", quest = 1716, title = "Devourer of Souls", npc = 6122, npcName = "Gakin the Darkbinder", minLevel = 20, qlvl = 20, pre = { 1717 }, preTitles = { [1717] = "Gakin's Summons" }, map = 1453, x = 25.3, y = 78.6, z = 101.5, f = "e" },
