						{ t = "turnin", quest = 1715, title = "The Slaughtered Lamb", npc = 6122, npcName = "Gakin the Darkbinder", map = 1453, x = 25.3, y = 78.6, z = 101.5, f = "e", only = { races = { "Gnome" } } },
