						{ t = "buy", npc = 12783, npcName = "Lieutenant Karter", item = 18244, itemName = "Black War Ram", map = 1453, x = 70.6, y = 55.9, f = "e", optional = true, note = "{item:18244}, {spell:826}, 100g" },
